import type { PluginSourceRef, RendererSource } from "../../types";

/**
 * Enough for a four-ink separation of an A1 image at the source resolution
 * cap with room to spare, so editing one large drawing never thrashes.
 */
const DEFAULT_MAX_BYTES = 256 * 1024 * 1024;
/** An image nothing has rendered from for this long is let go. */
const DEFAULT_MAX_IDLE_MS = 5 * 60 * 1000;
/** Ids are generated by the app window; anything longer is not one of ours. */
const MAX_ID_LENGTH = 64;

/** A source image the main process holds, under the id the app window gave it. */
export interface CachedSource extends RendererSource {
  id: string;
}

interface Entry {
  source: CachedSource;
  lastUsedAt: number;
}

/** Thrown by `PluginSourceCache.resolve` for an id it does not hold. */
export class PluginSourceMissingError extends Error {
  constructor(id: string) {
    super(`Source image "${id}" is not held by the main process.`);
    this.name = "PluginSourceMissingError";
  }
}

/**
 * The source images most recently sent from the app window, so a re-render
 * that changes only settings can name its image by id instead of copying it
 * across the process boundary again. Shared by every plugin: the app window
 * decides which image a render uses, and a plugin is only ever handed the
 * one its render names.
 *
 * Least recently used goes first once over budget. An image larger than the
 * whole budget is passed through without being kept.
 */
export class PluginSourceCache {
  /** In least-recently-used-first order, by re-insertion on every use. */
  private readonly entries = new Map<string, Entry>();
  private bytes = 0;

  constructor(
    private readonly maxBytes = DEFAULT_MAX_BYTES,
    private readonly maxIdleMs = DEFAULT_MAX_IDLE_MS,
  ) {}

  /**
   * The pixels `ref` stands for. Keeps them when `ref` carries them, and
   * looks them up when it does not, throwing `PluginSourceMissingError` if
   * they are not held — the app window then sends them again.
   */
  resolve(ref: PluginSourceRef, now = Date.now()): CachedSource {
    if (typeof ref?.id !== "string" || ref.id.length === 0 || ref.id.length > MAX_ID_LENGTH) {
      throw new Error("A render's source image has no valid id.");
    }

    if (ref.values === undefined) {
      const entry = this.entries.get(ref.id);
      if (!entry) throw new PluginSourceMissingError(ref.id);
      this.touch(ref.id, entry, now);
      return entry.source;
    }

    if (!(ref.values instanceof Uint8Array)) throw new Error("A render's source pixels must be a Uint8Array.");
    const source: CachedSource = { id: ref.id, width: ref.width, height: ref.height, values: ref.values };
    this.delete(ref.id);
    if (source.values.byteLength <= this.maxBytes) {
      this.entries.set(ref.id, { source, lastUsedAt: now });
      this.bytes += source.values.byteLength;
      this.trim();
    }
    return source;
  }

  /** Lets go of every image nothing has rendered from in a while. */
  sweep(now = Date.now()): void {
    for (const [id, entry] of this.entries) {
      if (now - entry.lastUsedAt > this.maxIdleMs) this.delete(id);
    }
  }

  clear(): void {
    this.entries.clear();
    this.bytes = 0;
  }

  get size(): number {
    return this.entries.size;
  }

  private touch(id: string, entry: Entry, now: number): void {
    entry.lastUsedAt = now;
    this.entries.delete(id);
    this.entries.set(id, entry);
  }

  private delete(id: string): void {
    const entry = this.entries.get(id);
    if (!entry) return;
    this.entries.delete(id);
    this.bytes -= entry.source.values.byteLength;
  }

  private trim(): void {
    for (const id of this.entries.keys()) {
      if (this.bytes <= this.maxBytes) return;
      this.delete(id);
    }
  }
}
